operation.add:
if (in_array($this->config->get('module_appnuno_status'), array('1', 1), true)) {
    $appnuno_route = isset($this->request->get['route']) && is_string($this->request->get['route']) ? $this->request->get['route'] : 'common/home';
    $appnuno_page = isset($this->request->server['REQUEST_URI']) && is_string($this->request->server['REQUEST_URI']) ? $this->request->server['REQUEST_URI'] : '/';
    $appnuno_args = 'page_route=' . rawurlencode($appnuno_route) . '&page=' . rawurlencode($appnuno_page);
    foreach (array('path', 'product_id', 'information_id', 'manufacturer_id') as $appnuno_key) {
        if (isset($this->request->get[$appnuno_key]) && is_string($this->request->get[$appnuno_key])) {
            $appnuno_args .= '&' . $appnuno_key . '=' . rawurlencode($this->request->get[$appnuno_key]);
        }
    }
    $appnuno_script = html_entity_decode($this->url->link('extension/module/appnuno/bootstrap', $appnuno_args, 'SSL'), ENT_QUOTES, 'UTF-8');
    if (!in_array($appnuno_script, $data['scripts'], true)) {
        $data['scripts'][] = $appnuno_script;
    }
}
